import { useMemo, useState, type KeyboardEvent, type ReactNode } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { loginSchema, registerSchema, resourceSchema, UserRole, type LoginInput, type RegisterInput, type ResourceInput } from "@reservehub/shared";
import { Activity, Archive, ArrowRight, Bell, Building2, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Clock3, Command, DoorOpen, Edit3, Ellipsis, Filter, Grid2X2, KeyRound, LayoutDashboard, LoaderCircle, LogOut, MapPin, Menu, Plus, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, UserRound, Users, X } from "lucide-react";
import { Area, AreaChart, Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { api, type ApiAdminUser, type ApiBooking, type ApiNotification, type ApiResource, type ApiUser } from "./api";

type Page = "Overview" | "Explore" | "My bookings" | "Calendar" | "Analytics" | "Admin" | "Settings";
type BookingTab = "upcoming" | "past" | "cancelled" | "all";
type AdminTab = "resources" | "members" | "audit";
type Notice = (message: string, tone?: "success" | "error") => void;

const accentMap: Record<string, string> = { MEETING_ROOM: "violet", DESK: "cyan", EQUIPMENT: "slate", STUDIO: "rose", EVENT_SPACE: "orange" };
const labelMap: Record<string, string> = { MEETING_ROOM: "Meeting room", DESK: "Hot desk", EQUIPMENT: "Equipment", STUDIO: "Studio", EVENT_SPACE: "Event space" };
const emptyWeek = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((day) => ({ day, hours: 0 }));

const accentFor = (resource: ApiResource) => accentMap[resource.resourceType] ?? "blue";
const typeLabel = (resource: ApiResource) => labelMap[resource.resourceType] ?? resource.resourceType;
const initials = (name: string) => name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
const dateText = (value: string) => new Intl.DateTimeFormat("en-US", { weekday: "short", month: "short", day: "numeric" }).format(new Date(value));
const timeText = (value: string) => new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit" }).format(new Date(value));
const inputDate = (value: string) => new Date(value).toISOString().slice(0, 10);
const inputTime = (value: string) => new Date(value).toISOString().slice(11, 16);
const apiDateTime = (date: string, time: string) => new Date(`${date}T${time}:00`).toISOString();
const tomorrow = () => inputDate(new Date(Date.now() + 86_400_000).toISOString());
const upcoming = (booking: ApiBooking) => booking.status === "CONFIRMED" && new Date(booking.endsAt).getTime() > Date.now();
const messageOf = (error: unknown) => error instanceof Error ? error.message : "Something went wrong. Please try again.";

export default function App() {
  const queryClient = useQueryClient();
  const session = useQuery({ queryKey: ["me"], queryFn: api.me, retry: false });
  const [mode, setMode] = useState<"login" | "register">("login");
  const [authError, setAuthError] = useState("");
  const auth = useMutation({ mutationFn: (input: LoginInput | RegisterInput) => mode === "login" ? api.login(input as LoginInput) : api.register(input as RegisterInput), onSuccess: (user) => { setAuthError(""); queryClient.setQueryData(["me"], user); }, onError: (error) => setAuthError(messageOf(error)) });
  if (session.isLoading) return <FullScreenState icon={<LoaderCircle className="spin" />} title="Loading your workspace" message="Restoring your secure session…" />;
  if (session.isError || !session.data) return <AuthScreen mode={mode} setMode={setMode} error={authError} loading={auth.isPending} onSubmit={(input) => auth.mutate(input)} />;
  return <Workspace user={session.data} />;
}

function Workspace({ user }: { user: ApiUser }) {
  const client = useQueryClient();
  const [page, setPage] = useState<Page>("Overview");
  const [mobileMenu, setMobileMenu] = useState(false);
  const [query, setQuery] = useState("");
  const [searchDraft, setSearchDraft] = useState("");
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [workspaceMenuOpen, setWorkspaceMenuOpen] = useState(false);
  const [notice, setNotice] = useState<{ message: string; tone: "success" | "error" } | null>(null);
  const [bookingResource, setBookingResource] = useState<ApiResource | null>(null);
  const [editingBooking, setEditingBooking] = useState<ApiBooking | null>(null);
  const [detailResource, setDetailResource] = useState<ApiResource | null>(null);
  const notify: Notice = (message, tone = "success") => { setNotice({ message, tone }); window.setTimeout(() => setNotice(null), 3500); };
  const resourcesQuery = useQuery({ queryKey: ["resources", "active"], queryFn: () => api.resources({ status: "ACTIVE" }) });
  const bookingsQuery = useQuery({ queryKey: ["bookings", "me"], queryFn: api.bookings });
  const notificationsQuery = useQuery({ queryKey: ["notifications"], queryFn: api.notifications });
  const overviewQuery = useQuery({ queryKey: ["analytics", "overview"], queryFn: api.analyticsOverview });
  const markRead = useMutation({ mutationFn: api.markNotificationRead, onSuccess: () => client.invalidateQueries({ queryKey: ["notifications"] }) });
  const cancel = useMutation({ mutationFn: api.cancelBooking, onSuccess: () => { client.invalidateQueries({ queryKey: ["bookings", "me"] }); notify("Booking cancelled and the slot is available again."); }, onError: (error) => notify(messageOf(error), "error") });
  const joinWaiting = useMutation({ mutationFn: api.joinWaitingList, onSuccess: () => { client.invalidateQueries({ queryKey: ["waiting-list"] }); setBookingResource(null); notify("You are now on the waiting list."); }, onError: (error) => notify(messageOf(error), "error") });
  const create = useMutation({ mutationFn: api.createBooking, onSuccess: () => { client.invalidateQueries({ queryKey: ["bookings", "me"] }); setBookingResource(null); notify("Booking confirmed. Your calendar is up to date."); }, onError: (error) => notify(messageOf(error), "error") });
  const update = useMutation({ mutationFn: ({ id, input }: { id: string; input: { startsAt?: string; endsAt?: string; notes?: string } }) => api.updateBooking(id, input), onSuccess: () => { client.invalidateQueries({ queryKey: ["bookings", "me"] }); setEditingBooking(null); notify("Booking updated successfully."); }, onError: (error) => notify(messageOf(error), "error") });
  const go = (next: Page) => { setPage(next); setMobileMenu(false); setNotificationOpen(false); setUserMenuOpen(false); setWorkspaceMenuOpen(false); };
  const onGlobalSearch = (event: KeyboardEvent<HTMLInputElement>) => { if (event.key === "Enter") { setQuery(searchDraft); go("Explore"); } };
  const resources = resourcesQuery.data ?? [];
  const bookings = bookingsQuery.data ?? [];
  const notifications = notificationsQuery.data ?? [];
  const logout = () => api.logout().then(() => client.clear()).catch((error) => notify(messageOf(error), "error"));
  return <div className="app-shell">
    <Sidebar user={user} page={page} open={mobileMenu} onPage={go} onLogout={logout} onOpenUserMenu={() => setUserMenuOpen((value) => !value)} workspaceOpen={workspaceMenuOpen} onToggleWorkspace={() => setWorkspaceMenuOpen((value) => !value)} />
    <main className="main-content">
      <header className="topbar">
        <button className="mobile-menu" onClick={() => setMobileMenu(true)} aria-label="Open navigation"><Menu size={20} /></button>
        <div className="breadcrumbs"><span>Workspace</span><ChevronRight size={14} /><b>{page === "Overview" ? "Dashboard" : page}</b></div>
        <div className="topbar-actions">
          <div className="global-search"><Search size={16} /><input aria-label="Search workspace" placeholder="Search resources…" value={searchDraft} onChange={(event) => setSearchDraft(event.target.value)} onKeyDown={onGlobalSearch} /><kbd><Command size={12} /> K</kbd></div>
          <div className="notification-wrap"><button className="icon-button notification-button" onClick={() => setNotificationOpen((value) => !value)} aria-label="Notifications"><Bell size={18} />{notifications.some((item) => !item.readAt) && <i />}</button>{notificationOpen && <NotificationPopover notifications={notifications} onRead={(id) => markRead.mutate(id)} />}</div>
          <button className="mini-avatar" onClick={() => setUserMenuOpen((value) => !value)} aria-label="Open account menu" aria-expanded={userMenuOpen}>{initials(user.fullName)}</button>

          {userMenuOpen && <UserMenu user={user} onPage={go} onLogout={logout} />}
        </div>
      </header>
      <div className="page-content"><PageContent page={page} user={user} resources={resources} bookings={bookings} notifications={notifications} overview={overviewQuery.data} query={query} setQuery={setQuery} onNavigate={go} onBook={setBookingResource} onDetails={setDetailResource} onCancel={(id) => cancel.mutate(id)} onEdit={setEditingBooking} onNotice={notify} /></div>
    </main>
    {(bookingResource || editingBooking) && <BookingModal resource={bookingResource ?? editingBooking!.resource} booking={editingBooking} submitting={create.isPending || update.isPending} onClose={() => { setBookingResource(null); setEditingBooking(null); }} onCreate={(input) => create.mutate(input)} onUpdate={(id, input) => update.mutate({ id, input })} onWaitingList={(input) => joinWaiting.mutate(input)} />}
    {detailResource && <ResourceDetails resource={detailResource} onClose={() => setDetailResource(null)} onBook={() => { setDetailResource(null); setBookingResource(detailResource); }} />}
    {notice && <div className={notice.tone === "error" ? "toast toast-error" : "toast"}><div className="toast-check"><Check size={15} /></div>{notice.message}<button onClick={() => setNotice(null)} aria-label="Dismiss message"><X size={15} /></button></div>}
  </div>;
}
function Sidebar({ user, page, open, onPage, onLogout, onOpenUserMenu, workspaceOpen, onToggleWorkspace }: { user: ApiUser; page: Page; open: boolean; onPage: (page: Page) => void; onLogout: () => void; onOpenUserMenu: () => void; workspaceOpen: boolean; onToggleWorkspace: () => void }) {
  const items: Array<{ page: Page; label: string; icon: typeof LayoutDashboard; adminOnly?: boolean }> = [
    { page: "Overview", label: "Dashboard", icon: LayoutDashboard },
    { page: "My bookings", label: "Bookings", icon: CalendarDays },
    { page: "Explore", label: "Spaces", icon: DoorOpen },
    { page: "Admin", label: "People", icon: Users, adminOnly: true },
    { page: "Analytics", label: "Reports", icon: Activity }
  ];
  return <><aside className={"sidebar " + (open ? "mobile-open" : "")}>
    <div className="brand"><div className="brand-mark"><Grid2X2 size={18} /></div><span>reserve<span>hub</span></span><small>24</small></div>
    <div className="workspace-switcher-wrap">
      <button className="workspace-switcher" onClick={onToggleWorkspace} aria-expanded={workspaceOpen}><div className="workspace-icon">AC</div><div><b>Acme Co.</b><span>Workspace</span></div><ChevronDown size={15} /></button>
      {workspaceOpen && <div className="workspace-menu"><b>Acme Co.</b><span>Current workspace</span><button onClick={() => onPage("Settings")}><Settings2 size={14} /> Workspace settings</button></div>}
    </div>
    <p className="nav-label">Workspace</p>
    <nav>{items.filter((item) => !item.adminOnly || user.role === UserRole.ADMIN).map(({ page: itemPage, label, icon: Icon }) => <button className={"nav-item " + (page === itemPage ? "active" : "")} key={label} onClick={() => onPage(itemPage)}><Icon size={18} /><span>{label}</span></button>)}</nav>
    <div className="sidebar-bottom">
      <button className={"nav-item muted " + (page === "Settings" ? "active" : "")} onClick={() => onPage("Settings")}><Settings2 size={18} /><span>Settings</span></button>
      <button className="nav-item muted" onClick={onLogout}><LogOut size={18} /><span>Sign out</span></button>
      <button className="profile" onClick={onOpenUserMenu} aria-label="Open account menu"><div className="avatar">{initials(user.fullName)}</div><div><b>{user.fullName}</b><span>{user.role === UserRole.ADMIN ? "Administrator" : "Member"}</span></div><Ellipsis size={17} /></button>
    </div>
  </aside>{open && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => onPage(page)} />}</>;
}
function UserMenu({ user, onPage, onLogout }: { user: ApiUser; onPage: (page: Page) => void; onLogout: () => void }) {
  return <div className="user-menu"><div className="user-menu-heading"><div className="avatar">{initials(user.fullName)}</div><div><b>{user.fullName}</b><span>{user.email}</span></div></div><button onClick={() => onPage("Settings")}><Settings2 size={14} /> Account settings</button><button onClick={() => onPage("Settings")}><KeyRound size={14} /> Change password</button><button className="danger-menu-item" onClick={onLogout}><LogOut size={14} /> Sign out</button></div>;
}
function PageContent({ page, user, resources, bookings, notifications, overview, query, setQuery, onNavigate, onBook, onDetails, onCancel, onEdit, onNotice }: { page: Page; user: ApiUser; resources: ApiResource[]; bookings: ApiBooking[]; notifications: ApiNotification[]; overview?: { totalBookings: number; confirmedBookings: number; activeResources: number }; query: string; setQuery: (value: string) => void; onNavigate: (page: Page) => void; onBook: (resource: ApiResource) => void; onDetails: (resource: ApiResource) => void; onCancel: (id: string) => void; onEdit: (booking: ApiBooking) => void; onNotice: Notice }) {
  if (page === "Overview") return <Overview user={user} resources={resources} bookings={bookings} notifications={notifications} overview={overview} onBook={onBook} onExplore={() => onNavigate("Explore")} onCancel={onCancel} onEdit={onEdit} onNotice={onNotice} />;
  if (page === "Explore") return <Explore resources={resources} query={query} setQuery={setQuery} onBook={onBook} onDetails={onDetails} />;
  if (page === "My bookings") return <MyBookings bookings={bookings} onBook={() => resources[0] && onBook(resources[0])} onCancel={onCancel} onEdit={onEdit} onNotice={onNotice} />;
  if (page === "Calendar") return <CalendarPage bookings={bookings} onEdit={onEdit} />;
  if (page === "Analytics") return <Analytics user={user} overview={overview} />;
  if (page === "Admin") return <Admin onNotice={onNotice} />;
  return <Settings user={user} notifications={notifications} onNotice={onNotice} />;
}

function Overview({ user, resources, bookings, notifications, overview, onBook, onExplore, onCancel, onEdit, onNotice }: { user: ApiUser; resources: ApiResource[]; bookings: ApiBooking[]; notifications: ApiNotification[]; overview?: { totalBookings: number; confirmedBookings: number; activeResources: number }; onBook: (resource: ApiResource) => void; onExplore: () => void; onCancel: (id: string) => void; onEdit: (booking: ApiBooking) => void; onNotice: Notice }) {
  const [dayOffset, setDayOffset] = useState(0);
  const displayDate = new Date(Date.now() + dayOffset * 86_400_000);
  const todayBookings = bookings.filter((booking) => inputDate(booking.startsAt) === inputDate(displayDate.toISOString()));
  const availableResources = resources.slice(0, 4);
  const unread = notifications.filter((item) => !item.readAt).length;
  const upcomingBookings = bookings.filter(upcoming).sort((a, b) => a.startsAt.localeCompare(b.startsAt)).slice(0, 3);
  return <div className="dashboard-page">
    <div className="dashboard-heading"><div><p className="eyebrow">Workspace overview</p><h1>Today</h1><p>{dateText(displayDate.toISOString())} · {user.fullName.split(" ")[0]}'s schedule</p></div><div className="dashboard-heading-actions"><button className="icon-button" onClick={() => setDayOffset((value) => value - 1)} aria-label="Previous day"><ChevronLeft size={17} /></button><button className="date-button" onClick={() => setDayOffset(0)}>Today</button><button className="icon-button" onClick={() => setDayOffset((value) => value + 1)} aria-label="Next day"><ChevronRight size={17} /></button><button className="select-button" onClick={() => { const firstResource = resources[0]; if (firstResource) onBook(firstResource); }} disabled={!resources[0]}><Plus size={14} /> New booking</button></div></div>
    <div className="dashboard-main-grid"><section className="panel schedule-panel"><div className="panel-heading"><div><h2>Schedule</h2><p>Bookings across your workspace</p></div><span className="data-pill">Live data</span></div><TimelineBoard date={displayDate} resources={resources} bookings={bookings} onEdit={onEdit} /></section><MiniMonthCalendar date={displayDate} onToday={() => setDayOffset(0)} /></div>
    <div className="dashboard-lower-grid"><section className="panel available-panel"><div className="panel-heading"><div><h2>Available now</h2><p>Resources ready to reserve</p></div><button className="text-button" onClick={onExplore}>View all <ArrowRight size={14} /></button></div><div className="available-resource-grid">{availableResources.map((resource) => <AvailableResourceCard key={resource.id} resource={resource} onBook={onBook} />)}</div>{!availableResources.length && <EmptyInline icon={<DoorOpen />} title="No active resources" message="Ask an administrator to add a resource." />}</section><AdminOverviewCard overview={overview} todayBookings={todayBookings} resources={resources} unread={unread} onNotice={onNotice} /></div>
    <section className="panel upcoming-panel"><div className="panel-heading"><div><h2>Upcoming bookings</h2><p>Your next reservations</p></div><button className="text-button" onClick={onExplore}>Explore resources <ArrowRight size={14} /></button></div>{upcomingBookings.map((booking) => <BookingRow key={booking.id} booking={booking} onEdit={onEdit} onCancel={onCancel} />)}{!upcomingBookings.length && <EmptyInline icon={<CalendarDays />} title="Nothing reserved yet" message="Find a resource for your next session." />}</section>
  </div>;
}

function TimelineBoard({ date, resources, bookings, onEdit }: { date: Date; resources: ApiResource[]; bookings: ApiBooking[]; onEdit: (booking: ApiBooking) => void }) {
  const hours = Array.from({ length: 10 }, (_, index) => index + 8);
  const rows = resources.slice(0, 5);
  const dayKey = inputDate(date.toISOString());
  return <div className="schedule-board"><div className="schedule-hours"><span />{hours.map((hour) => <span key={hour}>{String(hour).padStart(2, "0")}:00</span>)}</div>{rows.map((resource) => <div className="schedule-row" key={resource.id}><div className="schedule-resource"><span className={"schedule-dot " + accentFor(resource)} /><b>{resource.name}</b></div><div className="schedule-track">{hours.map((hour) => <i key={hour} />)}{bookings.filter((booking) => booking.resourceId === resource.id && inputDate(booking.startsAt) === dayKey && booking.status === "CONFIRMED").map((booking) => { const start = new Date(booking.startsAt); const end = new Date(booking.endsAt); const left = Math.max(0, (start.getHours() + start.getMinutes() / 60 - 8) * 10); const width = Math.max(4, (end.getTime() - start.getTime()) / 3_600_000 * 10); return <button key={booking.id} className={"schedule-booking " + accentFor(resource)} style={{ left: left + "%", width: width + "%" }} onClick={() => onEdit(booking)} title={booking.notes ?? "Booking"}>{booking.notes ?? "Reserved"}</button>; })}</div></div>)}{!rows.length && <EmptyInline icon={<CalendarDays />} title="No resources to display" message="Add resources to build your schedule." />}</div>;
}
function MiniMonthCalendar({ date, onToday }: { date: Date; onToday: () => void }) {
  const year = date.getFullYear();
  const month = date.getMonth();
  const firstDay = (new Date(year, month, 1).getDay() + 6) % 7;
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const cells = Array.from({ length: firstDay + daysInMonth }, (_, index) => index < firstDay ? null : index - firstDay + 1);
  return <section className="panel mini-calendar"><div className="mini-calendar-heading"><div><h2>{date.toLocaleDateString("en-US", { month: "long", year: "numeric" })}</h2><p>Quick month view</p></div><button className="today-button" onClick={onToday}>Today</button></div><div className="mini-calendar-week">{["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"].map((day) => <span key={day}>{day}</span>)}</div><div className="mini-calendar-grid">{cells.map((day, index) => <span className={day === date.getDate() ? "selected-day" : ""} key={index}>{day ?? ""}</span>)}</div><div className="calendar-summary"><span><i className="dot violet" /> {dateText(date.toISOString())}</span><b>Week view</b></div></section>;
}
function AvailableResourceCard({ resource, onBook }: { resource: ApiResource; onBook: (resource: ApiResource) => void }) {
  return <article className="available-resource-card"><div className="available-resource-image">{resource.imageUrl ? <img src={resource.imageUrl} alt={resource.name} loading="lazy" /> : <div className={"resource-fallback " + accentFor(resource)}><DoorOpen size={30} /></div>}<span className="availability-pill"><i /> Available</span></div><div className="available-resource-body"><div><h3>{resource.name}</h3><p>{typeLabel(resource)} · {resource.capacity ?? "—"} seats</p></div><button className="icon-book-button" onClick={() => onBook(resource)} aria-label={"Book " + resource.name}><Plus size={16} /></button></div></article>;
}
function AdminOverviewCard({ overview, todayBookings, resources, unread, onNotice }: { overview?: { totalBookings: number; confirmedBookings: number; activeResources: number }; todayBookings: ApiBooking[]; resources: ApiResource[]; unread: number; onNotice: Notice }) {
  const stats = [{ label: "Total spaces", value: String(overview?.activeResources ?? resources.length), tone: "violet", icon: <DoorOpen size={16} /> }, { label: "Active bookings", value: String(overview?.confirmedBookings ?? 0), tone: "cyan", icon: <CalendarDays size={16} /> }, { label: "Upcoming today", value: String(todayBookings.length), tone: "emerald", icon: <Clock3 size={16} /> }, { label: "Unread updates", value: String(unread), tone: "amber", icon: <Bell size={16} /> }];
  return <section className="panel admin-overview-card"><div className="panel-heading"><div><h2>Admin overview</h2><p>Workspace activity at a glance</p></div><button className="icon-button" onClick={() => onNotice("Admin overview is based on the latest workspace data.")} aria-label="About admin overview"><Ellipsis size={17} /></button></div><div className="admin-overview-list">{stats.map((stat) => <div className="admin-overview-item" key={stat.label}><span className={"admin-overview-icon " + stat.tone}>{stat.icon}</span><div><b>{stat.value}</b><small>{stat.label}</small></div></div>)}</div></section>;
}
function Explore({ resources, query, setQuery, onBook, onDetails }: { resources: ApiResource[]; query: string; setQuery: (value: string) => void; onBook: (resource: ApiResource) => void; onDetails: (resource: ApiResource) => void }) { const [type, setType] = useState("All types"); const [capacity, setCapacity] = useState(""); const [sort, setSort] = useState<"name" | "capacity">("name"); const [advanced, setAdvanced] = useState(false); const types = ["All types", ...Array.from(new Set(resources.map(typeLabel)))]; const visible = useMemo(() => resources.filter((resource) => (resource.name.toLowerCase().includes(query.toLowerCase()) || (resource.location ?? "").toLowerCase().includes(query.toLowerCase())) && (type === "All types" || typeLabel(resource) === type) && (!capacity || (resource.capacity ?? 0) >= Number(capacity))).sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : (b.capacity ?? 0) - (a.capacity ?? 0)), [resources, query, type, capacity, sort]); return <><PageHeading eyebrow="Resource library" title="Explore resources" description="Find the right space, desk, or equipment for your next session." action={<button className="primary-button" onClick={() => visible[0] && onBook(visible[0])}><Plus size={17} /> New booking</button>} /><div className="explore-toolbar"><div className="field-search"><Search size={17} /><input aria-label="Search resources" placeholder="Search by name or location…" value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="filter-pills">{types.map((item) => <button className={type === item ? "selected" : ""} key={item} onClick={() => setType(item)}>{item}</button>)}</div><button className={`filter-button ${advanced ? "selected-filter" : ""}`} onClick={() => setAdvanced((value) => !value)}><Filter size={16} /> Filters</button></div>{advanced && <div className="advanced-filters"><label>Minimum capacity<select value={capacity} onChange={(event) => setCapacity(event.target.value)}><option value="">Any size</option><option value="1">1+</option><option value="4">4+</option><option value="8">8+</option><option value="16">16+</option></select></label><button className="secondary-button" onClick={() => { setCapacity(""); setType("All types"); setQuery(""); }}>Clear filters</button></div>}<div className="results-meta"><span><b>{visible.length}</b> active resources</span><button onClick={() => setSort(sort === "name" ? "capacity" : "name")}>Sort: {sort === "name" ? "Name" : "Capacity"} <ChevronDown size={14} /></button></div><div className="resource-grid">{visible.map((resource) => <ResourceCard resource={resource} key={resource.id} onBook={onBook} onDetails={onDetails} />)}</div>{!visible.length && <div className="empty-state"><Search size={30} /><h3>No resources found</h3><p>Try another name, location, or filter.</p><button className="secondary-button" onClick={() => { setQuery(""); setCapacity(""); setType("All types"); }}>Clear search</button></div>}</>; }

function MyBookings({ bookings, onBook, onCancel, onEdit, onNotice }: { bookings: ApiBooking[]; onBook: () => void; onCancel: (id: string) => void; onEdit: (booking: ApiBooking) => void; onNotice: Notice }) { const [tab, setTab] = useState<BookingTab>("upcoming"); const waiting = useQuery({ queryKey: ["waiting-list"], queryFn: api.waitingList }); const remove = useMutation({ mutationFn: api.cancelWaitingList, onSuccess: () => { waiting.refetch(); onNotice("Removed from the waiting list."); }, onError: (error) => onNotice(messageOf(error), "error") }); const shown = bookings.filter((booking) => tab === "upcoming" ? upcoming(booking) : tab === "past" ? booking.status === "COMPLETED" || (booking.status === "CONFIRMED" && !upcoming(booking)) : tab === "cancelled" ? booking.status === "CANCELLED" : true); return <><PageHeading eyebrow="Your schedule" title="My bookings" description="Keep track of upcoming, past, and cancelled reservations." action={<button className="primary-button" onClick={onBook}><Plus size={17} /> New booking</button>} /><div className="booking-tabs">{([["upcoming", "Upcoming"], ["past", "Past"], ["cancelled", "Cancelled"], ["all", "All bookings"]] as const).map(([key, label]) => <button className={tab === key ? "active" : ""} key={key} onClick={() => setTab(key)}>{label}<span>{bookings.filter((booking) => key === "upcoming" ? upcoming(booking) : key === "past" ? booking.status === "COMPLETED" || (booking.status === "CONFIRMED" && !upcoming(booking)) : key === "cancelled" ? booking.status === "CANCELLED" : true).length}</span></button>)}</div><section className="panel bookings-list"><div className="list-toolbar"><div><h2>{tab === "upcoming" ? "Upcoming reservations" : tab === "past" ? "Past reservations" : "Booking history"}</h2><p>{shown.length} reservation(s)</p></div><button className="select-button" onClick={() => setTab("all")}><RefreshCw size={14} /> Show all</button></div>{shown.length ? shown.map((booking) => <BookingDetail key={booking.id} booking={booking} onCancel={onCancel} onEdit={onEdit} />) : <div className="empty-state compact"><CalendarDays size={30} /><h3>No bookings here</h3><p>Reserve a resource to see it in your schedule.</p><button className="primary-button" onClick={onBook}>Explore resources</button></div>}</section><section className="panel waiting-panel"><div className="list-toolbar"><div><h2>Waiting list</h2><p>Slots you want when they become available</p></div><button className="select-button" onClick={() => waiting.refetch()}><RefreshCw size={14} /> Refresh</button></div>{waiting.isLoading ? <InlineLoading /> : waiting.data?.length ? waiting.data.map((entry) => <div className="waiting-row" key={entry.id}><div><b>{dateText(entry.requestedStart)}</b><span>{timeText(entry.requestedStart)} – {timeText(entry.requestedEnd)} · Priority {entry.priority}</span></div><span className="status-text">{entry.status.toLowerCase()}</span><button className="cancel-button" onClick={() => remove.mutate(entry.id)}>Remove</button></div>) : <EmptyInline icon={<Clock3 />} title="No waiting-list entries" message="Join from the booking dialog when a desired time is unavailable." />}</section></>; }

function CalendarPage({ bookings, onEdit }: { bookings: ApiBooking[]; onEdit: (booking: ApiBooking) => void }) { const [offset, setOffset] = useState(0); const base = new Date(); base.setDate(base.getDate() - base.getDay() + 1 + offset * 7); const days = Array.from({ length: 7 }, (_, index) => { const day = new Date(base); day.setDate(base.getDate() + index); return day; }); return <><PageHeading eyebrow="Schedule" title="Calendar" description="See your reservations at a glance." action={<div className="calendar-actions"><button className="icon-button" onClick={() => setOffset((value) => value - 1)}><ChevronLeft size={17} /></button><button className="date-button" onClick={() => setOffset(0)}>Week of {dateText(days[0]!.toISOString())}</button><button className="icon-button" onClick={() => setOffset((value) => value + 1)}><ChevronRight size={17} /></button></div>} /><div className="calendar-legend"><span><i className="dot violet" /> My bookings</span><span><i className="dot gray" /> Available time</span><button className="today-button" onClick={() => setOffset(0)}>Today</button></div><section className="panel calendar-panel"><div className="week-header"><div className="timezone">GMT</div>{days.map((day) => <div key={day.toISOString()}><span>{day.toLocaleDateString("en-US", { weekday: "short" })}</span><b>{day.getDate()}</b></div>)}</div><div className="calendar-body"><div className="time-column">{Array.from({ length: 10 }, (_, index) => <span key={index}>{String(index + 8).padStart(2, "0")}:00</span>)}</div>{days.map((day) => <div className="day-column" key={day.toISOString()}>{Array.from({ length: 10 }, (_, index) => <div className="hour-line" key={index} />)}{bookings.filter(upcoming).filter((booking) => inputDate(booking.startsAt) === inputDate(day.toISOString())).map((booking) => <button className={`calendar-event ${accentFor(booking.resource)}-event`} key={booking.id} style={{ top: Math.max(4, (new Date(booking.startsAt).getHours() - 8) * 60), height: Math.max(42, (new Date(booking.endsAt).getTime() - new Date(booking.startsAt).getTime()) / 60_000) }} onClick={() => onEdit(booking)}><b>{booking.resource.name}</b><span>{timeText(booking.startsAt)} – {timeText(booking.endsAt)}</span></button>)}</div>)}</div></section></>; }

function Analytics({ user, overview }: { user: ApiUser; overview?: { totalBookings: number; confirmedBookings: number; activeResources: number } }) { const usage = useQuery({ queryKey: ["analytics", "usage"], queryFn: api.resourceUsage, enabled: user.role === UserRole.ADMIN }); const peak = useQuery({ queryKey: ["analytics", "peak"], queryFn: api.peakHours, enabled: user.role === UserRole.ADMIN }); return <><PageHeading eyebrow="Workspace intelligence" title="Analytics" description="Understand how your team uses shared resources." action={<button className="select-button" onClick={() => window.alert("Analytics are calculated from confirmed bookings.")}><CalendarDays size={15} /> Current data <ChevronDown size={14} /></button>} /><div className="stats-grid analytics-stats"><StatCard icon={<Activity />} label="Workspace bookings" value={String(overview?.totalBookings ?? 0)} change="All time" tone="violet" /><StatCard icon={<Clock3 />} label="Confirmed bookings" value={String(overview?.confirmedBookings ?? 0)} change="Currently active" tone="cyan" /><StatCard icon={<Users />} label="Active resources" value={String(overview?.activeResources ?? 0)} change="Available to members" tone="emerald" /><StatCard icon={<Sparkles />} label="Peak hour" value={peak.data?.[0] ? `${String(peak.data[0].hour).padStart(2, "0")}:00` : "—"} change="Booking starts" tone="amber" /></div>{user.role !== UserRole.ADMIN ? <div className="permission-card"><ShieldCheck size={22} /><div><h3>Admin analytics are restricted</h3><p>Ask a workspace administrator for resource usage and peak-hour reporting.</p></div></div> : <div className="dashboard-grid analytics-grid"><section className="panel chart-panel"><div className="panel-heading"><div><h2>Resource usage</h2><p>Confirmed bookings by resource</p></div></div><div className="bar-chart-wrap">{usage.isLoading ? <InlineLoading /> : <ResponsiveContainer width="100%" height="100%"><BarChart data={usage.data?.map((item) => ({ name: item.resourceName, value: Number(item.usageCount) })) ?? []} layout="vertical" margin={{ left: 15, right: 25 }}><CartesianGrid horizontal={false} stroke="#edf0f5" /><XAxis type="number" axisLine={false} tickLine={false} /><YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={100} /><Tooltip contentStyle={{ border: "1px solid #eaecf2", borderRadius: 10 }} /><Bar dataKey="value" fill="#7562e8" radius={[0, 5, 5, 0]} barSize={17} /></BarChart></ResponsiveContainer>}</div></section><section className="panel insight-panel"><div className="panel-heading"><div><h2>Peak hours</h2><p>When the workspace is most active</p></div><Sparkles size={18} className="insight-spark" /></div>{peak.data?.length ? peak.data.slice(0, 5).map((item, index) => <div className="insight" key={item.hour}><div className="insight-number">{String(index + 1).padStart(2, "0")}</div><div><b>{String(item.hour).padStart(2, "0")}:00 – {String(Number(item.hour) + 1).padStart(2, "0")}:00</b><p>{item.usageCount} booking starts in this hour.</p></div></div>) : <EmptyInline icon={<Activity />} title="Not enough data yet" message="Peak hours appear after bookings are created." />}</section></div>}</>; }

function Admin({ onNotice }: { onNotice: Notice }) {
  const client = useQueryClient();
  const [tab, setTab] = useState<AdminTab>("resources");
  const [archived, setArchived] = useState(false);
  const [createOpen, setCreateOpen] = useState(false);
  const [passwordTarget, setPasswordTarget] = useState<ApiAdminUser | null>(null);
  const active = useQuery({ queryKey: ["admin-resources", "active"], queryFn: () => api.resources({ status: "ACTIVE" }) });
  const old = useQuery({ queryKey: ["admin-resources", "archived"], queryFn: () => api.resources({ status: "ARCHIVED" }), enabled: archived });
  const members = useQuery({ queryKey: ["admin", "members"], queryFn: api.adminUsers, enabled: tab === "members" });
  const logs = useQuery({ queryKey: ["admin", "logs"], queryFn: api.auditLogs, enabled: tab === "audit" });
  const resources = [...(active.data ?? []), ...(archived ? old.data ?? [] : [])];
  const create = useMutation({ mutationFn: api.createResource, onSuccess: () => { client.invalidateQueries({ queryKey: ["admin-resources"] }); setCreateOpen(false); onNotice("Resource created successfully."); }, onError: (error) => onNotice(messageOf(error), "error") });
  const status = useMutation({ mutationFn: async ({ id, next }: { id: string; next: "ACTIVE" | "ARCHIVED" }) => { if (next === "ARCHIVED") await api.archiveResource(id); else await api.updateResource(id, { status: next }); }, onSuccess: () => { client.invalidateQueries({ queryKey: ["admin-resources"] }); onNotice("Resource status updated."); }, onError: (error) => onNotice(messageOf(error), "error") });
  const role = useMutation({ mutationFn: ({ id, value }: { id: string; value: typeof UserRole.MEMBER | typeof UserRole.ADMIN }) => api.updateUserRole(id, value), onSuccess: () => { client.invalidateQueries({ queryKey: ["admin", "members"] }); onNotice("Member role updated."); }, onError: (error) => onNotice(messageOf(error), "error") });
  return <><PageHeading eyebrow="Workspace controls" title="Admin console" description="Manage resources, members, roles, passwords, and audit history." action={tab === "resources" ? <button className="primary-button" onClick={() => setCreateOpen(true)}><Plus size={17} /> Add resource</button> : undefined} /><div className="admin-tabs"><button className={tab === "resources" ? "active" : ""} onClick={() => setTab("resources")}><Building2 size={16} /> Resources <span>{resources.length}</span></button><button className={tab === "members" ? "active" : ""} onClick={() => setTab("members")}><Users size={16} /> Members</button><button className={tab === "audit" ? "active" : ""} onClick={() => setTab("audit")}><ShieldCheck size={16} /> Audit log</button></div>{tab === "resources" && <section className="panel admin-panel"><div className="list-toolbar"><div><h2>All resources</h2><p>Manage availability and workspace inventory</p></div><label className="toggle"><input type="checkbox" checked={archived} onChange={(event) => setArchived(event.target.checked)} /><span />Show archived</label></div>{active.isLoading ? <InlineLoading /> : <div className="resource-table"><div className="table-head"><span>Resource</span><span>Type</span><span>Location</span><span>Capacity</span><span>Status</span><span /></div>{resources.map((resource) => <div className="table-row" key={resource.id}><div className="table-resource"><div className={"table-icon " + accentFor(resource)}><DoorOpen size={16} /></div><b>{resource.name}</b></div><span>{typeLabel(resource)}</span><span>{resource.location ?? "—"}</span><span>{resource.capacity ?? "—"}</span><span className="status-badge table-status"><i />{resource.status.toLowerCase()}</span><button className="row-menu" onClick={() => status.mutate({ id: resource.id, next: resource.status === "ACTIVE" ? "ARCHIVED" : "ACTIVE" })}>{resource.status === "ACTIVE" ? <Archive size={16} /> : <RefreshCw size={16} />}</button></div>)}</div>}</section>}{tab === "members" && <Members users={members.data ?? []} loading={members.isLoading} onRoleChange={(id, value) => role.mutate({ id, value })} onResetPassword={setPasswordTarget} />}{tab === "audit" && <AuditLogs logs={logs.data ?? []} loading={logs.isLoading} />}{createOpen && <ResourceForm submitting={create.isPending} onClose={() => setCreateOpen(false)} onSave={(input) => create.mutate(input)} />}{passwordTarget && <MemberPasswordModal user={passwordTarget} onClose={() => setPasswordTarget(null)} onNotice={onNotice} />}</>;
}

function ChangePasswordForm({ onNotice }: { onNotice: Notice }) {
  const form = useForm<{ currentPassword: string; newPassword: string; confirmPassword: string }>({ defaultValues: { currentPassword: "", newPassword: "", confirmPassword: "" } });
  const change = useMutation({ mutationFn: api.changePassword, onSuccess: () => { form.reset(); onNotice("Password changed. Other sessions have been signed out."); }, onError: (error) => onNotice(messageOf(error), "error") });
  const submit = (values: { currentPassword: string; newPassword: string; confirmPassword: string }) => {
    if (values.newPassword !== values.confirmPassword) { form.setError("confirmPassword", { type: "validate", message: "Passwords do not match" }); return; }
    change.mutate({ currentPassword: values.currentPassword, newPassword: values.newPassword });

  };
  return <section className="panel security-form-panel"><div className="panel-heading"><div><h2>Change password</h2><p>Use a new password to protect your account.</p></div><KeyRound size={19} className="settings-icon" /></div><form className="settings-form" onSubmit={form.handleSubmit(submit)}><label>Current password<input type="password" autoComplete="current-password" {...form.register("currentPassword", { required: "Current password is required" })} />{form.formState.errors.currentPassword && <small>{form.formState.errors.currentPassword.message}</small>}</label><div className="form-grid"><label>New password<input type="password" autoComplete="new-password" {...form.register("newPassword", { required: "New password is required", minLength: { value: 8, message: "Use at least 8 characters" } })} />{form.formState.errors.newPassword && <small>{form.formState.errors.newPassword.message}</small>}</label><label>Confirm new password<input type="password" autoComplete="new-password" {...form.register("confirmPassword", { required: "Please confirm the new password" })} />{form.formState.errors.confirmPassword && <small>{form.formState.errors.confirmPassword.message}</small>}</label></div><button className="primary-button" disabled={change.isPending}>{change.isPending ? "Changing…" : "Change password"}</button></form></section>;
}
function Settings({ user, notifications, onNotice }: { user: ApiUser; notifications: ApiNotification[]; onNotice: Notice }) {
  const client = useQueryClient();
  const [theme, setTheme] = useState(() => localStorage.getItem("reservehub-theme") ?? "light");
  const [calendarView, setCalendarView] = useState(() => localStorage.getItem("reservehub-calendar-view") ?? "week");
  const [policyOpen, setPolicyOpen] = useState(false);
  const form = useForm<{ fullName: string }>({ defaultValues: { fullName: user.fullName } });
  const save = useMutation({ mutationFn: (value: string) => api.updateProfile(value), onSuccess: (next) => { client.setQueryData(["me"], next); onNotice("Profile saved."); }, onError: (error) => onNotice(messageOf(error), "error") });
  const changeTheme = (value: string) => { setTheme(value); localStorage.setItem("reservehub-theme", value); document.documentElement.dataset.theme = value; onNotice((value === "light" ? "Light" : "Dim") + " theme selected."); };
  const changeCalendarView = (value: string) => { setCalendarView(value); localStorage.setItem("reservehub-calendar-view", value); onNotice("Calendar view saved."); };
  return <><PageHeading eyebrow="Workspace preferences" title="Settings" description="Manage your profile and personal UI preferences." /><div className="settings-grid"><section className="panel settings-panel"><div className="panel-heading"><div><h2>Profile</h2><p>Visible to your workspace.</p></div><UserRound size={19} className="settings-icon" /></div><form className="settings-form" onSubmit={form.handleSubmit((values) => save.mutate(values.fullName))}><label>Full name<input {...form.register("fullName", { required: "Full name is required" })} />{form.formState.errors.fullName && <small>{form.formState.errors.fullName.message}</small>}</label><label>Email address<input value={user.email} disabled /></label><label>Role<input value={user.role === UserRole.ADMIN ? "Administrator" : "Member"} disabled /></label><button className="primary-button" disabled={save.isPending}>{save.isPending ? "Saving…" : "Save profile"}</button></form></section><section className="panel settings-panel"><div className="panel-heading"><div><h2>Preferences</h2><p>Customize your ReserveHub experience.</p></div><Settings2 size={19} className="settings-icon" /></div><label className="preference-row"><span><b>Interface theme</b><small>Choose a comfortable appearance.</small></span><select value={theme} onChange={(event) => changeTheme(event.target.value)}><option value="light">Light</option><option value="dim">Dim</option></select></label><label className="preference-row"><span><b>Calendar view</b><small>Default view for your schedule.</small></span><select value={calendarView} onChange={(event) => changeCalendarView(event.target.value)}><option value="week">Week</option><option value="day">Day</option></select></label><div className="preference-row"><span><b>Unread notifications</b><small>{notifications.filter((item) => !item.readAt).length} waiting for review.</small></span><Bell size={17} /></div></section></div><ChangePasswordForm onNotice={onNotice} /><section className="panel security-panel"><ShieldCheck size={20} /><div><h2>Session security</h2><p>Your session uses an HTTP-only cookie. Passwords and tokens are never stored in localStorage.</p></div><button className="secondary-button" onClick={() => setPolicyOpen(true)}>Review policy</button></section>{policyOpen && <SecurityPolicyModal onClose={() => setPolicyOpen(false)} />}</>;
}

function BookingModal({ resource, booking, submitting, onClose, onCreate, onUpdate, onWaitingList }: { resource: ApiResource; booking: ApiBooking | null; submitting: boolean; onClose: () => void; onCreate: (input: { resourceId: string; startsAt: string; endsAt: string; notes?: string; idempotencyKey: string }) => void; onUpdate: (id: string, input: { startsAt?: string; endsAt?: string; notes?: string }) => void; onWaitingList: (input: { resourceId: string; requestedStart: string; requestedEnd: string; priority: number }) => void }) { const form = useForm<{ date: string; start: string; end: string; notes: string }>({ defaultValues: { date: booking ? inputDate(booking.startsAt) : tomorrow(), start: booking ? inputTime(booking.startsAt) : "09:00", end: booking ? inputTime(booking.endsAt) : "10:00", notes: booking?.notes ?? "" } }); const [error, setError] = useState(""); const submit = (values: { date: string; start: string; end: string; notes: string }) => { if (values.end <= values.start) { setError("End time must be after the start time."); return; } setError(""); const startsAt = apiDateTime(values.date, values.start); const endsAt = apiDateTime(values.date, values.end); if (booking) onUpdate(booking.id, { startsAt, endsAt, notes: values.notes }); else onCreate({ resourceId: resource.id, startsAt, endsAt, notes: values.notes, idempotencyKey: crypto.randomUUID() }); }; return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal"><div className="modal-header"><div><p className="eyebrow">{booking ? "Edit reservation" : "New reservation"}</p><h2>{booking ? "Update booking" : `Book ${resource.name}`}</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><div className="modal-resource"><div className={`resource-thumb ${accentFor(resource)}`}><DoorOpen size={20} /></div><div><b>{typeLabel(resource)}</b><span><MapPin size={13} /> {resource.location ?? "No location"}</span></div><span className="capacity-label"><Users size={13} /> {resource.capacity ?? "—"}</span></div><form onSubmit={form.handleSubmit(submit)}><div className="form-grid"><label>Date<input type="date" min={inputDate(new Date().toISOString())} {...form.register("date", { required: "Pick a date" })} />{form.formState.errors.date && <small>{form.formState.errors.date.message}</small>}</label><label>Notes<input placeholder="e.g. Team sync" {...form.register("notes")} /></label><label>Starts at<input type="time" {...form.register("start", { required: true })} /></label><label>Ends at<input type="time" {...form.register("end", { required: true })} /></label></div>{error && <div className="form-error">{error}</div>}<div className="availability-note"><Check size={15} /><span><b>Availability is checked by the server.</b><small>{dateText(`${form.watch("date")}T12:00:00`)} · {form.watch("start")} – {form.watch("end")}</small></span></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button>{!booking && <button type="button" className="waiting-button" onClick={() => onWaitingList({ resourceId: resource.id, requestedStart: apiDateTime(form.getValues("date"), form.getValues("start")), requestedEnd: apiDateTime(form.getValues("date"), form.getValues("end")), priority: 0 })}><Clock3 size={14} /> Join waiting list</button>}<button type="submit" className="primary-button" disabled={submitting}>{submitting ? "Saving…" : booking ? "Save changes" : "Confirm booking"} {!submitting && <ArrowRight size={15} />}</button></div></form></div></div>; }

function ResourceDetails({ resource, onClose, onBook }: { resource: ApiResource; onClose: () => void; onBook: () => void }) { const availability = useQuery({ queryKey: ["availability", resource.id], queryFn: () => api.availability(resource.id, new Date().toISOString(), new Date(Date.now() + 7 * 86_400_000).toISOString()) }); const suggestions = useQuery({ queryKey: ["suggestions", resource.id], queryFn: () => api.suggestions(resource.id) }); return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal detail-modal"><div className="modal-header"><div><p className="eyebrow">Resource details</p><h2>{resource.name}</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><div className={"detail-hero " + accentFor(resource)}>{resource.imageUrl ? <img src={resource.imageUrl} alt={resource.name} /> : <DoorOpen size={31} />}<span className="status-badge"><i />{resource.status.toLowerCase()}</span></div><div className="detail-content"><div className="detail-stat-grid"><div><MapPin size={15} /><span>Location<b>{resource.location ?? "—"}</b></span></div><div><Users size={15} /><span>Capacity<b>{resource.capacity ?? "—"} people</b></span></div><div><Clock3 size={15} /><span>Timezone<b>{resource.timezone}</b></span></div></div><p className="resource-description">{resource.description ?? "No description has been added yet."}</p><h3>Next availability</h3>{availability.isLoading ? <InlineLoading /> : availability.data?.length ? availability.data.slice(0, 3).map((slot) => <div className="slot-row" key={slot.startsAt}><span>{dateText(slot.startsAt)}</span><b>{timeText(slot.startsAt)} – {timeText(slot.endsAt)}</b></div>) : <EmptyInline icon={<Check />} title="Wide open" message="No confirmed bookings in the next 7 days." />}<h3>Similar resources</h3>{suggestions.isLoading ? <InlineLoading /> : <div className="suggestion-list">{suggestions.data?.slice(0, 3).map((item) => <button key={item.id} onClick={onClose}><span>{item.name}</span><small>{typeLabel(item)} · {item.capacity ?? "—"} people</small></button>)}</div>}<div className="modal-footer"><button className="secondary-button" onClick={onClose}>Close</button><button className="primary-button" onClick={onBook} disabled={resource.status !== "ACTIVE"}>Book this resource <ArrowRight size={15} /></button></div></div></div></div>; }

function ResourceCard({ resource, onBook, onDetails }: { resource: ApiResource; onBook: (resource: ApiResource) => void; onDetails: (resource: ApiResource) => void }) { return <article className="resource-card"><button className={"resource-card-visual " + accentFor(resource)} onClick={() => onDetails(resource)}>{resource.imageUrl ? <img src={resource.imageUrl} alt={resource.name} loading="lazy" /> : <div className="visual-grid" />}<span className="status-badge"><i />available</span><div className="visual-icon"><DoorOpen size={30} /></div></button><div className="resource-card-body"><div className="resource-card-title"><button onClick={() => onDetails(resource)}><h3>{resource.name}</h3><p>{typeLabel(resource)}</p></button><button className="row-menu" onClick={() => onDetails(resource)}><Ellipsis size={18} /></button></div><div className="resource-location"><MapPin size={14} />{resource.location ?? "No location"} <span>·</span> {resource.timezone}</div><div className="resource-capacity"><Users size={14} /> Up to {resource.capacity ?? "—"} people</div><button className="outline-button" onClick={() => onBook(resource)}>View availability <ArrowRight size={15} /></button></div></article>; }
function ResourceMini({ resource, onBook }: { resource: ApiResource; onBook: (resource: ApiResource) => void }) { return <div className="resource-mini">{resource.imageUrl ? <img className="resource-mini-image" src={resource.imageUrl} alt="" loading="lazy" /> : <div className={"resource-thumb " + accentFor(resource)}><DoorOpen size={19} /></div>}<div><b>{resource.name}</b><span><MapPin size={12} /> {resource.location ?? "No location"}</span></div><button onClick={() => onBook(resource)} aria-label={"Book " + resource.name}><Plus size={16} /></button></div>; }
function BookingActions({ booking, onEdit, onCancel }: { booking: ApiBooking; onEdit: (booking: ApiBooking) => void; onCancel: (id: string) => void }) {
  const [open, setOpen] = useState(false);
  if (!upcoming(booking)) return null;
  return <div className="booking-actions"><button className="row-menu" onClick={() => setOpen((value) => !value)} aria-label="Booking actions" aria-expanded={open}><Ellipsis size={18} /></button>{open && <div className="row-action-menu"><button onClick={() => { setOpen(false); onEdit(booking); }}><Edit3 size={13} /> Edit booking</button><button onClick={() => { setOpen(false); onCancel(booking.id); }}><Archive size={13} /> Cancel booking</button></div>}</div>;
}
function BookingRow({ booking, onEdit, onCancel }: { booking: ApiBooking; onEdit: (booking: ApiBooking) => void; onCancel: (id: string) => void }) {
  return <div className="booking-row"><div className={"resource-dot " + accentFor(booking.resource)}><Building2 size={17} /></div><div className="booking-info"><b>{booking.resource.name}</b><span>{dateText(booking.startsAt)} · {timeText(booking.startsAt)} – {timeText(booking.endsAt)}</span></div><span className="booking-purpose">{booking.notes ?? "Reservation"}</span><BookingActions booking={booking} onEdit={onEdit} onCancel={onCancel} /></div>;
}
function BookingDetail({ booking, onCancel, onEdit }: { booking: ApiBooking; onCancel: (id: string) => void; onEdit: (booking: ApiBooking) => void }) {
  return <div className="booking-detail"><div className={"detail-date " + accentFor(booking.resource)}><b>{new Date(booking.startsAt).getDate()}</b><span>{new Date(booking.startsAt).toLocaleDateString("en-US", { month: "short" })}</span></div><div className="booking-detail-main"><div className="detail-title"><h3>{booking.resource.name}</h3><span className={"status-text " + booking.status.toLowerCase()}>{booking.status.toLowerCase()}</span></div><p><MapPin size={14} />{booking.resource.location ?? "No location"}</p><p><Clock3 size={14} />{timeText(booking.startsAt)} – {timeText(booking.endsAt)} · {booking.notes ?? "Reservation"}</p></div>{upcoming(booking) && <><button className="edit-button" onClick={() => onEdit(booking)}><Edit3 size={14} /> Edit</button><button className="cancel-button" onClick={() => onCancel(booking.id)}>Cancel</button></>}<BookingActions booking={booking} onEdit={onEdit} onCancel={onCancel} /></div>;
}
function NotificationPopover({ notifications, onRead }: { notifications: ApiNotification[]; onRead: (id: string) => void }) { return <div className="notification-popover"><div className="popover-heading"><div><b>Notifications</b><span>{notifications.filter((item) => !item.readAt).length} unread</span></div><Bell size={16} /></div>{notifications.length ? notifications.slice(0, 6).map((item) => <button className={`notification-item ${item.readAt ? "read" : ""}`} key={item.id} onClick={() => onRead(item.id)}><div className="activity-icon violet"><Bell size={13} /></div><div><b>{item.title}</b><p>{item.message}</p><time>{dateText(item.createdAt)}</time></div>{!item.readAt && <i />}</button>) : <EmptyInline icon={<Check />} title="All caught up" message="No notifications yet." />}</div>; }
function PageHeading({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="page-heading"><div>{eyebrow && <p className="eyebrow">{eyebrow}</p>}<h1>{title}</h1>{description && <p className="heading-description">{description}</p>}</div>{action}</div>; }
function StatCard({ icon, label, value, change, tone }: { icon: ReactNode; label: string; value: string; change: string; tone: string }) { return <div className="stat-card"><div className={`stat-icon ${tone}`}>{icon}</div><div className="stat-meta"><span>{label}</span><strong>{value}</strong><small>{change}</small></div><div className="sparkline"><span /><span /><span /><span /><span /><span /></div></div>; }
function ActivityItem({ icon, color, title, detail, time }: { icon: ReactNode; color: string; title: string; detail: string; time: string }) { return <div className="activity-item"><div className={`activity-icon ${color}`}>{icon}</div><div><b>{title}</b><p>{detail}</p></div><time>{time}</time></div>; }
function EmptyInline({ icon, title, message }: { icon: ReactNode; title: string; message: string }) { return <div className="empty-inline">{icon}<div><b>{title}</b><span>{message}</span></div></div>; }
function InlineLoading() { return <div className="inline-loading"><LoaderCircle className="spin" size={20} />Loading…</div>; }
function SecurityPolicyModal({ onClose }: { onClose: () => void }) {
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal"><div className="modal-header"><div><p className="eyebrow">Security policy</p><h2>How ReserveHub protects your session</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><div className="policy-list"><p>Sessions use an HTTP-only cookie and are not exposed to browser JavaScript.</p><p>Passwords are stored as Argon2 hashes and are never stored in localStorage.</p><p>Changing a password invalidates existing sessions for that account.</p><p>Admin password changes are recorded in the audit log.</p></div><div className="modal-footer policy-footer"><button className="primary-button" onClick={onClose}>Close</button></div></div></div>;
}
function FullScreenState({ icon, title, message }: { icon: ReactNode; title: string; message: string }) { return <div className="full-screen-state">{icon}<h2>{title}</h2><p>{message}</p></div>; }
function UsageChart({ bookings }: { bookings: ApiBooking[] }) { const data = emptyWeek.map((entry) => ({ ...entry, hours: bookings.filter((booking) => booking.status === "CONFIRMED" && new Date(booking.startsAt).toLocaleDateString("en-US", { weekday: "short" }) === entry.day).reduce((sum, booking) => sum + (new Date(booking.endsAt).getTime() - new Date(booking.startsAt).getTime()) / 3_600_000, 0) })); return <ResponsiveContainer width="100%" height="100%"><AreaChart data={data}><defs><linearGradient id="usageGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#7562e8" stopOpacity={0.24} /><stop offset="100%" stopColor="#7562e8" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="#edf0f5" /><XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: "#9299aa", fontSize: 12 }} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "#9299aa", fontSize: 12 }} /><Tooltip contentStyle={{ border: "1px solid #eaecf2", borderRadius: 10 }} /><Area type="monotone" dataKey="hours" stroke="#7562e8" strokeWidth={2.5} fill="url(#usageGradient)" /></AreaChart></ResponsiveContainer>; }

function AuthScreen({ mode, setMode, error, loading, onSubmit }: { mode: "login" | "register"; setMode: (mode: "login" | "register") => void; error: string; loading: boolean; onSubmit: (input: LoginInput | RegisterInput) => void }) {
  const login = useForm<LoginInput>({ resolver: zodResolver(loginSchema) });
  const register = useForm<RegisterInput>({ resolver: zodResolver(registerSchema) });
  const [show, setShow] = useState(false);
  return <div className="auth-screen"><div className="auth-brand"><div className="brand-mark"><Grid2X2 size={18} /></div><span>reserve<span>hub</span></span><small>24</small></div><div className="auth-card"><div className="auth-heading"><p className="eyebrow">Workspace access</p><h1>{mode === "login" ? "Welcome back" : "Create your account"}</h1><p>{mode === "login" ? "Sign in to manage your reservations." : "Start organizing shared resources."}</p></div>{error && <div className="form-error">{error}</div>}{mode === "login" ? <form onSubmit={login.handleSubmit(onSubmit)}><label>Email address<input type="email" placeholder="you@company.com" {...login.register("email")} />{login.formState.errors.email && <small>{login.formState.errors.email.message}</small>}</label><label>Password<div className="password-field"><input type={show ? "text" : "password"} placeholder="••••••••" {...login.register("password")} /><button type="button" onClick={() => setShow((value) => !value)}>{show ? "Hide" : "Show"}</button></div></label><div className="form-options"><label className="checkbox"><input type="checkbox" {...login.register("rememberMe")} /> Remember me</label><button type="button" className="link-button" onClick={() => window.alert("Please contact your company administrator to reset your password.")}>Forgot password?</button></div><button className="primary-button full-button" disabled={loading}>{loading ? "Signing in…" : "Sign in"} {!loading && <ArrowRight size={15} />}</button></form> : <form onSubmit={register.handleSubmit(onSubmit)}><label>Full name<input placeholder="Your name" {...register.register("fullName")} />{register.formState.errors.fullName && <small>{register.formState.errors.fullName.message}</small>}</label><label>Email address<input type="email" placeholder="you@company.com" {...register.register("email")} />{register.formState.errors.email && <small>{register.formState.errors.email.message}</small>}</label><label>Password<div className="password-field"><input type={show ? "text" : "password"} placeholder="At least 8 characters" {...register.register("password")} /><button type="button" onClick={() => setShow((value) => !value)}>{show ? "Hide" : "Show"}</button></div></label><button className="primary-button full-button" disabled={loading}>{loading ? "Creating account…" : "Create account"} {!loading && <ArrowRight size={15} />}</button></form>}<div className="auth-switch">{mode === "login" ? "Don't have an account?" : "Already have an account?"}<button onClick={() => setMode(mode === "login" ? "register" : "login")}>{mode === "login" ? "Create one" : "Sign in"}</button></div></div><p className="auth-footer">© 2026 ReserveHub · Secure workspace reservations</p></div>;
}



function ResourceForm({ submitting, onClose, onSave }: { submitting: boolean; onClose: () => void; onSave: (input: ResourceInput) => void }) { const form = useForm<ResourceInput>({ resolver: zodResolver(resourceSchema), defaultValues: { resourceType: "MEETING_ROOM", timezone: "Asia/Bangkok" } }); return <div className="modal-backdrop"><div className="modal"><div className="modal-header"><div><p className="eyebrow">Admin resource</p><h2>Add a resource</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><form className="resource-form" onSubmit={form.handleSubmit(onSave)}><label>Name<input placeholder="Atlas Boardroom" {...form.register("name")} />{form.formState.errors.name && <small>{form.formState.errors.name.message}</small>}</label><label>Description<textarea placeholder="Describe the resource" {...form.register("description")} /></label><div className="form-grid"><label>Type<select {...form.register("resourceType")}><option value="MEETING_ROOM">Meeting room</option><option value="DESK">Desk</option><option value="EQUIPMENT">Equipment</option><option value="STUDIO">Studio</option></select></label><label>Capacity<input type="number" min="1" {...form.register("capacity", { valueAsNumber: true })} /></label><label>Location<input placeholder="Bangkok HQ" {...form.register("location")} /></label><label>Timezone<input {...form.register("timezone")} /></label></div><div className="modal-footer"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={submitting}>{submitting ? "Creating…" : "Create resource"}</button></div></form></div></div>; }

function Members({ users, loading, onRoleChange, onResetPassword }: { users: ApiAdminUser[]; loading: boolean; onRoleChange: (id: string, role: typeof UserRole.MEMBER | typeof UserRole.ADMIN) => void; onResetPassword: (user: ApiAdminUser) => void }) {
  return <section className="panel admin-panel"><div className="list-toolbar"><div><h2>Workspace members</h2><p>Manage account roles, access, and passwords.</p></div></div>{loading ? <InlineLoading /> : <div className="member-list">{users.map((member) => <div className="member-row" key={member.id}><div className="avatar">{initials(member.fullName)}</div><div><b>{member.fullName}</b><span>{member.email}</span></div><span className="member-created">Joined {dateText(member.createdAt)}</span><select value={member.role} onChange={(event) => onRoleChange(member.id, event.target.value as typeof UserRole.MEMBER | typeof UserRole.ADMIN)}><option value="MEMBER">Member</option><option value="ADMIN">Admin</option></select><button className="edit-button" type="button" onClick={() => onResetPassword(member)}><KeyRound size={13} /> Set password</button></div>)}</div>}</section>;
}
function MemberPasswordModal({ user, onClose, onNotice }: { user: ApiAdminUser; onClose: () => void; onNotice: Notice }) {
  const form = useForm<{ newPassword: string; confirmPassword: string }>({ defaultValues: { newPassword: "", confirmPassword: "" } });
  const reset = useMutation({ mutationFn: (newPassword: string) => api.resetUserPassword(user.id, newPassword), onSuccess: () => { onClose(); onNotice("Password updated. Other existing sessions have been signed out."); }, onError: (error) => onNotice(messageOf(error), "error") });
  const submit = (values: { newPassword: string; confirmPassword: string }) => {
    if (values.newPassword !== values.confirmPassword) { form.setError("confirmPassword", { type: "validate", message: "Passwords do not match" }); return; }
    reset.mutate(values.newPassword);
  };
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal"><div className="modal-header"><div><p className="eyebrow">Admin security</p><h2>Set user password</h2></div><button className="close-button" onClick={onClose}><X size={18} /></button></div><form className="settings-form" onSubmit={form.handleSubmit(submit)}><p className="modal-help">Set a new password for <b>{user.fullName}</b> ({user.email}). The user will need the new password at their next sign in.</p><label>New password<input type="password" autoComplete="new-password" {...form.register("newPassword", { required: "New password is required", minLength: { value: 8, message: "Use at least 8 characters" } })} />{form.formState.errors.newPassword && <small>{form.formState.errors.newPassword.message}</small>}</label><label>Confirm new password<input type="password" autoComplete="new-password" {...form.register("confirmPassword", { required: "Please confirm the new password" })} />{form.formState.errors.confirmPassword && <small>{form.formState.errors.confirmPassword.message}</small>}</label><div className="modal-footer"><button type="button" className="secondary-button" onClick={onClose}>Cancel</button><button className="primary-button" disabled={reset.isPending}>{reset.isPending ? "Updating…" : "Update password"}</button></div></form></div></div>;
}
function AuditLogs({ logs, loading }: { logs: Array<{ id: string; action: string; entityType: string; entityId: string | null; createdAt: string }>; loading: boolean }) { return <section className="panel admin-panel"><div className="list-toolbar"><div><h2>Audit log</h2><p>Privileged changes recorded by the API.</p></div></div>{loading ? <InlineLoading /> : logs.length ? <div className="audit-list">{logs.map((log) => <div className="audit-row" key={log.id}><div className="activity-icon violet"><ShieldCheck size={14} /></div><div><b>{log.action.replaceAll("_", " ")}</b><span>{log.entityType}{log.entityId ? ` · ${log.entityId.slice(0, 8)}` : ""}</span></div><time>{dateText(log.createdAt)} {timeText(log.createdAt)}</time></div>)}</div> : <EmptyInline icon={<ShieldCheck />} title="No audit events" message="Admin actions will appear here." />}</section>; }
